INSERT INTO public.webhook_events (id, provider, external_id, processed_at, customer_phone, payload) VALUES (85, 'whatsapp', 'bot_1774479654471_127075247759470@lid', '2026-03-25 23:00:54.471', '213560900657@c.us', '{"event": "message", "payload": {"body": "Je vois que vous avez une liste de suggestions et de demandes pour am├®liorer notre syst├¿me et notre service. Je vais r├®sumer ce que j''ai compris :\n\n1. Ajouter des pages de d├®filement pour le traitement et la caisse.\n2. Permettre de valider et de commander directement sur le kiosk sans passer par l''├®tape \"Termin├®e la commande\".\n3. D├®placer des produits (peut-├¬tre pour les rendre plus accessibles ou les regrouper par cat├®gorie).\n4. Enlever l''e accent (probablement pour faciliter la saisie de texte).\n5. Ajouter le num├®ro de WhatsApp sur les tickets de support pour que les clients puissent contacter directement la personne qui a envoy├® le ticket.\n6. Ajouter le logo de Robotech sur la page d''accueil du kiosk.\n7. Changer les prix sur la page de traitement.\n\nJe vais prendre note de ces suggestions et les transmettre ├á notre ├®quipe de d├®veloppement pour qu''ils puissent les prendre en compte. Merci de votre feedback ! Autre chose je peux vous aider ? ­ƒÿè", "type": "text", "fromMe": true}}');
