INSERT INTO public.webhook_events (id, provider, external_id, processed_at, customer_phone, payload) VALUES (480, 'whatsapp', 'bot_1774867326338_213560900657@c.us', '2026-03-30 10:42:06.338', '213560900657@c.us', '{"event": "message", "payload": {"body": "Je suis d├®sol├®, mais je ne peux pas vous donner directement le code Netflix. Cependant, je peux vous aider ├á r├®cup├®rer votre code si vous avez achet├® un compte Netflix chez nous.\n\nPour ce faire, veuillez me fournir les informations suivantes :\n\n* Le type de compte Netflix que vous avez achet├® (par exemple, Netflix 1 mois, Netflix 12 mois, etc.)\n* La date de votre achat\n* Le num├®ro de commande ou la r├®f├®rence de votre achat\n\nUne fois que j''ai ces informations, je peux vous aider ├á r├®cup├®rer votre code Netflix.\n\nVoici les options de comptes Netflix que nous proposons :\n\n* Netflix 45 jours : 1000 DA\n* D''autres options peuvent ├¬tre disponibles, veuillez me demander pour plus d''informations\n\nVeuillez me choisir l''option que vous avez achet├®e pour que je puisse vous aider ├á r├®cup├®rer votre code.\n\nAutre chose je peux vous aider ? ­ƒÿè", "type": "text", "fromMe": true}}');
